"""Stress test: the misere P-position congruence is exact across a wide range.

Compares the O(r*m) dynamic-programming oracle against the O(1) closed form
r ≡ 1 (mod m+1) for many granularities and long ladders, reporting the first
disagreement (there is none)."""
from __future__ import annotations
from typing import List, Optional, Tuple


def solve(m: int, r_max: int, misere: bool) -> List[bool]:
    wins = [False] * (r_max + 1)
    wins[0] = misere
    for r in range(1, r_max + 1):
        wins[r] = any((not wins[r - s]) for s in range(1, min(m, r) + 1))
    return wins


def first_mismatch(m: int, r_max: int) -> Optional[Tuple[int, bool, bool]]:
    wins = solve(m, r_max, misere=True)
    for r in range(r_max + 1):
        oracle_p = not wins[r]
        formula_p = (r % (m + 1) == 1)
        if oracle_p != formula_p:
            return (r, oracle_p, formula_p)
    return None


def main() -> None:
    for m in range(1, 20):
        mm = first_mismatch(m, 500)
        print(f"m={m:2d}: first mismatch up to r=500 -> {mm}")


if __name__ == "__main__":
    main()

