function ESCALATION_OUTCOMES(m, r_max, misere):
    wins[0..r_max] <- False
    wins[0] <- misere            # True for misère, False for normal
    for r from 1 to r_max:
        wins[r] <- False
        for s from 1 to min(m, r):
            if not wins[r - s]:
                wins[r] <- True; break
    return wins

function IS_P_POSITION(m, r, misere):
    t <- 1 if misere else 0
    return (r mod (m + 1)) == t

function OPTIMAL_STEP(m, r, misere):
    t <- 1 if misere else 0
    if r == 0 or (r mod (m+1)) == t:
        return None            # no winning move
    return (r - t) mod (m + 1)
